/* A paced illustrated company story. No quiz, timer or animation-dependent gate. */
(() => {
  'use strict';
  const arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg>';
  const back='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 12H5m6-6-6 6 6 6"/></svg>';
  const check='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>';
  const historySource='https://ochakovo.ru/istoriya/';
  const chapters=[
    {id:'beginning',label:'Начало',era:'1978 — 1980',title:'Завод для большого города',source:historySource,more:'Первое название — Московский пивобезалкогольный комбинат. Слово «Очаково» вошло в название позже. В материалах компании начало истории связано с подготовкой Москвы к Олимпиаде-80.',beats:[
      {title:'Москва готовилась к большой встрече',text:'Скоро город должен был принять гостей Олимпиады-80. Нужны были напитки — и предприятие, способное выпускать их в большом объёме.',action:'Увидеть начало',coach:'У этой истории была большая городская задача — встретить гостей со всего мира.'},
      {title:'18 декабря 1978 года',text:'Московский комбинат открылся. Сначала запустили пивоваренное производство, а уже через год — выпуск безалкогольных напитков.',action:'Открыть следующий цех',coach:'Первая страница открыта. За одним заводом постепенно вырастали разные производства.'},
      {title:'Большой замысел стал настоящим заводом',text:'За привычной бутылкой появились цеха, оборудование и люди. Но построить предприятие было только первым шагом. Дальше предстояло научиться меняться.',action:'Что было дальше',coach:'Завод появился. Теперь начинается история его развития.'}
    ]},
    {id:'renewal',label:'Перемены',era:'1988 — 1990-е',title:'Заново собрать завод',source:historySource,more:'В 1994 году компания начала разливать пиво в ПЭТ-бутылки, а в 1995-м — в алюминиевые банки. Новая упаковка была частью перемен, вместе с обновлением оборудования и производственных линий.',beats:[
      {title:'Первое десятилетие оказалось непростым',text:'Оборудование старело, а работе предприятия требовалось обновление. В 1988 году комбинат возглавил Алексей Кочетов. Начался новый этап.',action:'Начать обновление',coach:'В истории есть не только открытия. Иногда следующая глава начинается с трудностей.',mood:'think'},
      {title:'Прибыль возвращалась в производство',text:'В 1993 году предприятие стало акционерным обществом. Средства направляли на реконструкцию: она продолжалась пять лет, постепенно меняя завод.',action:'Посмотреть на перемены',coach:'Обновление происходило шаг за шагом — через оборудование, цеха и новые линии.'},
      {title:'Другие линии. Больше возможностей.',text:'На смену старому оборудованию приходило современное. Появлялись новые форматы упаковки. Параллельно команда решала другую задачу — сохранить вкус традиционного кваса в промышленном производстве.',action:'Отправиться за рецептом',coach:'Новая техника пригодилась для задачи, которая начиналась далеко от заводских стен.',mood:'success'}
    ]},
    {id:'expedition',label:'Экспедиции',era:'1990-е',title:'Вкус, который помнили люди',source:historySource,more:'У кваса нет одного-единственного вкуса. В рецептах сочетаются разные злаки и способы подготовки солода. Позже собранные в экспедициях материалы дали начало и тёмному «Очаковскому», и белому квасу «Семейный секрет».',beats:[
      {title:'Ответ искали не только в лаборатории',text:'Чтобы перенести традиционный квас в промышленное производство, сотрудники отправлялись в российские деревни. Там сохранялись домашние рецепты и опыт квасоваров.',action:'Продолжить путь',coach:'Теперь история выходит за ворота завода — навстречу людям и их опыту.'},
      {title:'Сначала слушали и собирали',text:'Рецепты записывали и изучали. Важен был сам принцип: не заменить традицию знакомым названием, а разобраться, как получается её вкус.',action:'Заглянуть в записи',coach:'За технологией стоят наблюдения, рецепты и человеческая память.'},
      {title:'Дорога вернулась на производство',text:'Материалы экспедиций помогли создать «Очаковский». Домашний опыт стал основой для работы технологов — теперь его нужно было воспроизвести в другом масштабе.',action:'Проследить развитие',coach:'Здесь встречаются две части истории: традиционный рецепт и возможности большого предприятия.'}
    ]},
    {id:'kvass',label:'Традиция',era:'2013 · традиция продолжается',title:'Два начала одного вкуса',source:'https://ochakovo.ru/kak-delayut-nastoyashhij-kvas/',more:'Разница начинается ещё с солода. Для тёмного «Очаковского» его обжаривают: так появляется аромат ржаной корочки. Для белого кваса «Семейный секрет. Традиционный» солод не обжаривают.',beats:[
      {title:'К записанным рецептам вернулись снова',text:'Квас «Очаковский» уже продолжал историю экспедиций. Но собранные материалы могли дать начало и другим рецептам. Важной основой оставалось двойное брожение.',action:'Увидеть две культуры',coach:'Это не две версии одного ингредиента, а две разные культуры, работающие вместе.'},
      {title:'У традиционного вкуса — две культуры',text:'Дрожжи и молочнокислые бактерии работают вместе. Этот принцип команда сохранила при производстве кваса в промышленном масштабе.',action:'К следующему рецепту',coach:'За сохранением вкуса стоит совместная работа технологов, производства и лаборатории.'},
      {title:'Рецепты получили новое продолжение',text:'К собранным материалам возвращались снова. В 2013 году на их основе технологи разработали белый квас «Семейный секрет».',action:'К знакомым вкусам',coach:'Записанный когда-то рецепт может стать началом новой главы спустя годы.',mood:'success'}
    ]},
    {id:'growth',label:'Масштаб',era:'2000 — 2007',title:'История вышла за пределы Москвы',source:historySource,more:'У компании развивалась и собственная сырьевая база: в 2003 году открылась солодовня. А с 2005 года на производство стали приглашать посетителей — чтобы путь напитка можно было увидеть своими глазами.',beats:[
      {title:'После обновления — новые города',text:'Завершив модернизацию московского предприятия, компания начала развивать региональные площадки. Первым филиалом стал завод в Краснодаре.',action:'Открыть следующую площадку',coach:'Один завод стал началом сети производственных площадок.'},
      {title:'Следующая точка — Пенза',text:'Строительство в Пензе начали в 2001 году. В 2003-м завод заработал. Вместе с площадками росли производственные команды.',action:'Продолжить маршрут',coach:'У каждой новой площадки появлялась своя команда, а история оставалась общей.'},
      {title:'В 2007 году — Тюмень',text:'Тюменский завод строили с 2004 года и открыли в 2007-м. Москва, Краснодар, Пенза и Тюмень стали частью одной производственной географии.',action:'Вернуться к рецептам',coach:'Заводы в разных городах связывает общая работа над напитками.'}
    ]},
    {id:'new-tastes',label:'Новинки',era:'2022',title:'Знакомые вкусы. Новая глава.',source:'https://nonalco.ochakovo.ru/istoriya/',more:'У этой главы появилось продолжение: позже к классической CoolCola добавились версия Zero без сахара и вишнёвая Cherry. Линейка развивалась — один знакомый вкус становился отправной точкой для новых.',beats:[
      {title:'Компания продолжала пробовать новое',text:'В 2022 году появилась новая линейка прохладительных напитков: CoolCola, Fancy, Street и Toness.',action:'Рассмотреть линейку',coach:'Возможно, ты уже встречал эти названия. Теперь они связаны с историей компании.'},
      {title:'Четыре названия — разные вкусы',text:'Классическая кола, апельсин, лимон и лайм, тоник. Нажми на бутылку, чтобы рассмотреть каждый напиток.',action:'Что у них общего',coach:'Каждый напиток — отдельный рецепт. Выбери бутылку — рассмотрим её вкус.'},
      {title:'Традиции не мешают экспериментам',text:'Рядом с квасом развивались другие категории. Их технологии различаются, но за каждой новой бутылкой остаётся работа большой команды.',action:'Познакомиться с командой',coach:'Квас и газировка проходят разные пути. Их объединяют люди, которые отвечают за результат.'}
    ]},
    {id:'people',label:'Команда',era:'Сегодня',title:'История продолжается людьми',source:'https://ochakovo.ru/rabota/',more:'В материалах компании для студентов названы лаборатория, цех розлива, технологический цех и складской комплекс. Инженерное направление знакомит с автоматикой и оборудованием. Задачи новичка и допуск определяет наставник.',beats:[
      {title:'Не только даты и названия',text:'Лаборатория проверяет показатели. Операторы ведут линию. Инженеры разбираются в оборудовании. Склад связывает готовую продукцию с заказом.',action:'Заглянуть внутрь',coach:'Теперь на карте видны не просто здания, а работа разных людей.'},
      {title:'Завод можно увидеть изнутри',text:'С 2005 года «Очаково» проводит экскурсии на производство. А для студентов знакомство может продолжиться практикой — рядом с наставником.',action:'Выбрать первую задачу',coach:'Начать можно с любопытства: посмотреть, спросить и попробовать простую рабочую задачу.'},
      {title:'Следующая маленькая глава — твоя',text:'Теперь попробуй одну из задач команды. Выбирай по интересу: это знакомство с профессиями, а не экзамен.',action:'Начать',coach:'С какого участка начнём твою смену?',mood:'welcome'}
    ]}
  ];
  chapters.forEach((c,i)=>{c.scene=i;});
  chapters.splice(3,0,chapters.splice(4,1)[0]);
  const drinks=[{id:'cola',name:'CoolCola',flavour:'Классическая кола',color:'#44291f',label:'#b3082c'},{id:'fancy',name:'Fancy',flavour:'Апельсин',color:'#efa62a',label:'#cf4d12'},{id:'street',name:'Street',flavour:'Лимон и лайм',color:'#d8dc96',label:'#427a3f'},{id:'toness',name:'Toness',flavour:'Тоник',color:'#e8e8da',label:'#3d525a'}];
  const roleChoices=[{id:'lab',title:'Лаборатория',path:'M8 3h8M10 3v7l-5 9a1.4 1.4 0 0 0 1.2 2h11.6a1.4 1.4 0 0 0 1.2-2l-5-9V3M8 15h8'},{id:'line',title:'Линия розлива',path:'M7 3h4v5l2 3v10H5V11l2-3ZM17 8h4v13h-4M3 23h20'},{id:'engineering',title:'Инженерия',path:'M4 4h16v16H4ZM8 8h8M8 12h3m-3 4h8M16 11v2'},{id:'warehouse',title:'Склад',path:'m3 7 9-4 9 4v11l-9 4-9-4ZM3 7l9 4 9-4M12 11v11'}];
  const roleStart=id=>'Начать '+(id==='warehouse'?'со склада':'с '+({lab:'лаборатории',line:'линии розлива',engineering:'инженерного участка'}[id]));
  const icon=path=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg>`;
  function drinkBottle(d){return `<span class="chronicle-bottle" style="--drink:${d.color};--label:${d.label}" aria-hidden="true"><i class="cb-cap"></i><i class="cb-neck"></i><span class="cb-body"><span class="cb-liquid"></span><span class="cb-label">${d.name}</span><i></i></span></span>`;}
  function machineSvg(modern){return `<svg viewBox="0 0 900 340" fill="none" aria-hidden="true"><path d="M0 290h900" stroke="${modern?'#b8a992':'#aaa69e'}" stroke-width="30"/><g fill="${modern?'#fffdf7':'#d7d3ca'}" stroke="${modern?'#a08e77':'#9c9a94'}" stroke-width="3"><rect x="65" y="58" width="150" height="210" rx="20"/><rect x="325" y="78" width="220" height="185" rx="9"/><rect x="665" y="45" width="160" height="220" rx="12"/></g><path d="M140 54V25h600v20M215 165h110m220 0h120" stroke="${modern?'#b6a38a':'#aaa69e'}" stroke-width="9"/><path d="M85 165h110v75H85Z" fill="${modern?'#e2b84b':'#bbb6aa'}" opacity=".6"/><g stroke="${modern?'#d50032':'#a39b8d'}" stroke-width="3"><circle cx="140" cy="108" r="25"/><path class="chronicle-gauge" d="m140 108 13-14"/><rect x="351" y="104" width="169" height="85" rx="3"/><path d="M371 128h39m15 0h29m15 0h31m-129 21h95m-95 21h42"/></g><g fill="${modern?'#d50032':'#9c9486'}"><circle cx="370" cy="224" r="8"/><circle cx="404" cy="224" r="8"/><circle cx="438" cy="224" r="8"/><rect x="690" y="79" width="108" height="23" rx="3"/></g><path d="M690 126h108m-108 24h108m-108 24h108m-108 24h108m-108 24h108" stroke="${modern?'#d5c9b7':'#b4ada2'}" stroke-width="6"/><g fill="${modern?'#fffdf7':'#c9c5ba'}" stroke="${modern?'#af9880':'#9d998f'}" stroke-width="2">${[270,590,850].map(x=>`<g class="chronicle-line-bottle"><path d="M${x-7} 217h14v17l8 10v35h-30v-35l8-10Z"/><path d="M${x-15} 253h30" stroke="${modern?'#d50032':'#9b9486'}" stroke-width="18"/></g>`).join('')}</g><g fill="${modern?'#8c7862':'#8f8a80'}">${Array.from({length:18},(_,i)=>`<circle cx="${15+i*51}" cy="290" r="8"/>`).join('')}</g></svg>`;}
  function fermentScene(beat){return `<img class="chronicle-art c-art-recipe" src="assets/history-recipes.png" alt="Иллюстрация зерна, записной книжки и традиционной посуды" width="1536" height="1024"><div class="chronicle-ferment ${beat>0?'is-alive':''}"><div class="culture-token culture-yeast"><svg viewBox="0 0 60 60" aria-hidden="true"><g fill="#d5a344" stroke="#a56d1e" stroke-width="2"><ellipse cx="25" cy="30" rx="14" ry="18"/><ellipse cx="43" cy="17" rx="8" ry="10"/></g></svg><span>Дрожжи</span></div><svg class="chronicle-tank" viewBox="0 0 200 260" fill="none" aria-hidden="true"><path d="M65 14h70v32l30 27v137l-30 25H65l-30-25V73l30-27Z" fill="#fffdf8" stroke="#ac9980" stroke-width="3"/><path d="M40 100h120v107l-28 22H68l-28-22Z" fill="#d4a03a" opacity=".65"/><path d="M49 88v107m17-181h68M56 235v20m88-20v20" stroke="#bba78a" stroke-width="4"/><path d="M90 32h20M92 56h16" stroke="#d50032" stroke-width="4"/></svg><div class="chronicle-bubbles" aria-hidden="true">${Array.from({length:9},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div class="culture-token culture-bacteria"><svg viewBox="0 0 60 60" aria-hidden="true"><g fill="#cd5570" stroke="#a62443" stroke-width="2"><rect x="11" y="11" width="14" height="35" rx="7" transform="rotate(-25 18 28)"/><rect x="36" y="20" width="13" height="30" rx="6.5" transform="rotate(20 42 35)"/></g></svg><span>Молочнокислые<br>бактерии</span></div><strong class="ferment-result">Двойное брожение</strong></div>${beat===2?`<div class="chronicle-kvass-pair">${[{name:'Очаковский',color:'#a45e28',label:'#762f1f'},{name:'Семейный секрет',color:'#e0bc74',label:'#b89557'}].map(d=>`<div>${drinkBottle(d)}<strong>${d.name}</strong></div>`).join('')}</div>`:''}`;}
  function geography(beat){
    const places=[{name:'Москва',year:'1978',x:16.7,y:44.4},{name:'Краснодар',year:'2000',x:43.3,y:77.8},{name:'Пенза',year:'2003',x:55.6,y:40.3},{name:'Тюмень',year:'2007',x:82.2,y:18.1}];
    const routes=['M150 160C250 160 250 280 390 280','M150 160C280 160 320 145 500 145','M150 160C350 160 410 65 740 65'];
    return `<img class="chronicle-art chronicle-map-ground" src="assets/factory-map.png" alt="Условная иллюстрация производственных площадок" width="1536" height="1024"><svg class="chronicle-geography" viewBox="0 0 900 360" preserveAspectRatio="none" fill="none" aria-hidden="true"><g stroke="#d4c8b8" stroke-width="2">${routes.map(d=>`<path d="${d}"/>`).join('')}</g>${routes.map((d,i)=>i<=beat?`<path class="chronicle-route" d="${d}" stroke="#d50032" stroke-width="3" stroke-dasharray="650"/>`:'').join('')}</svg><div class="chronicle-places">${places.map((p,i)=>`<span class="chronicle-place ${i<=beat+1?'is-open':''}" style="--x:${p.x}%;--y:${p.y}%"><i></i><strong>${p.name}</strong><small>${p.year}</small></span>`).join('')}</div><span class="chronicle-picture-note">Схема развития · не географическая карта</span>`;
  }
  function mount(container,onComplete){
    let chapter=0,beat=0,selectedRole='lab',selectedDrink='',cleaned=false,done=false;const visited=new Set();const animations=new Set();let context=null;
    const root=document.createElement('section');root.className='chronicle';root.setAttribute('aria-label','Мини-история компании Очаково');container.replaceChildren(root);
    const media=window.matchMedia('(prefers-reduced-motion: reduce)');
    const motion=()=>!media.matches&&window.GameMotion?.enabled()!==false&&!document.hidden;
    const coach=()=>{const b=chapters[chapter].beats[beat];window.GameMotion?.coach({mood:b.mood||'welcome',text:b.coach});};
    function dispose(){animations.forEach(t=>t.kill());animations.clear();if(context){context.revert();context=null;}}
    function scene(){const sceneIndex=chapters[chapter].scene;
      if(sceneIndex===0)return `<img class="chronicle-art chronicle-factory-art" src="assets/history-factory.png" alt="Художественная иллюстрация комбината конца 1970-х годов" width="1536" height="1024"><div class="chronicle-opening-date"><span>${beat===0?'Москва, накануне Олимпиады':'18 декабря'}</span><strong>1978</strong><small>${beat===0?'Большой замысел':'Открытие комбината'}</small></div><div class="chronicle-windows" aria-hidden="true"><i></i><i></i><i></i></div><svg class="chronicle-power" viewBox="0 0 900 360" aria-hidden="true"><path d="M350 285H670L750 210H860" fill="none" stroke="#d50032" stroke-width="2" stroke-dasharray="600"/><g fill="#d50032" stroke="white" stroke-width="2"><circle cx="350" cy="285" r="5"/><circle cx="515" cy="285" r="5"/><circle cx="670" cy="285" r="5"/><circle cx="750" cy="210" r="5"/></g></svg><span class="chronicle-picture-note">Историческая иллюстрация</span>`;
      if(sceneIndex===1)return `<div class="chronicle-old-machine">${machineSvg(false)}</div><div class="chronicle-new-machine" style="clip-path:inset(0 0 0 ${[100,48,0][beat]}%)">${machineSvg(true)}</div><div class="chronicle-rebuild-label"><span>${beat===0?'Нужны перемены':beat===1?'Реконструкция':'Новые возможности'}</span><strong>${beat===0?'1988':beat===1?'1993':'1990-е'}</strong></div><span class="chronicle-picture-note">Образ обновления · схема</span>`;
      if(sceneIndex===2)return `<img class="chronicle-art chronicle-expedition-art" src="assets/${beat<2?'history-expedition-v4.png':'history-recipes.png'}" alt="${beat<2?'Собирательная иллюстрация встречи исследователей с жительницей деревни, не архивный снимок':'Иллюстрация записной книжки, зерна и квасной посуды'}" width="1536" height="1024">${beat===2?'<div class="chronicle-field-note"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M5 3h14v18H5zm4 4h6m-6 4h6m-6 4h4"/></svg><span>Рецепты из экспедиций</span></div>':''}<span class="chronicle-picture-note">Собирательная иллюстрация · не архивная фотография</span>`;
      if(sceneIndex===3)return fermentScene(beat)+`<span class="chronicle-picture-note">Упрощённая схема · условная упаковка</span>`;
      if(sceneIndex===4)return geography(beat);
      if(sceneIndex===5)return `<div class="chronicle-drinks ${beat===0?'is-introduction':''}">${drinks.map((d,i)=>`<button type="button" data-chronicle="drink" data-value="${d.id}" class="chronicle-drink ${selectedDrink===d.id?'is-picked':''}" aria-pressed="${selectedDrink===d.id}" ${beat===0&&i>0?'disabled':''}>${drinkBottle(d)}<strong>${d.name}</strong><span>${beat>0?d.flavour:'2022'}</span></button>`).join('')}</div><div class="chronicle-drink-caption" role="status" aria-live="polite">${selectedDrink?drinks.find(d=>d.id===selectedDrink).name+' · '+drinks.find(d=>d.id===selectedDrink).flavour:beat===0?'Новая линейка прохладительных напитков':beat===1?'Кола · апельсин · лимон и лайм · тоник':'Разные рецептуры. Общая команда.'}</div><span class="chronicle-picture-note">Условная упаковка</span>`;
      return `<img class="chronicle-art chronicle-team-art" src="assets/factory-map.png" alt="Иллюстрация завода и участков, на которых работает команда" width="1536" height="1024"><div class="chronicle-team-spots">${roleChoices.map((r,i)=>`<span class="chronicle-team-spot spot-${r.id}" style="--n:${i}">${icon(r.path)}<strong>${r.title}</strong></span>`).join('')}</div><span class="chronicle-picture-note">Иллюстрация производственной команды</span>`;
    }
    function render(withMotion=true){
      dispose();visited.add(chapter);const c=chapters[chapter],b=c.beats[beat],last=chapter===chapters.length-1&&beat===c.beats.length-1;root.dataset.chapter=c.id;root.dataset.beat=beat;
      root.innerHTML=`<nav class="chronicle-chapters" aria-label="Главы истории">${chapters.map((x,i)=>`<button type="button" data-chronicle="chapter" data-value="${i}" class="${i===chapter?'is-current':''} ${visited.has(i)?'is-visited':''}" ${i===chapter?'aria-current="step"':''} title="${x.title}"><span>${i+1}</span>${x.label}</button>`).join('')}</nav><div class="chronicle-scene" aria-label="${c.title}">${scene()}</div><div class="chronicle-narration"><div class="chronicle-position"><span>${c.era}</span><span>Глава ${chapter+1} из ${chapters.length}</span></div><div class="chronicle-copy" aria-live="polite" aria-atomic="true"><h1 tabindex="-1">${b.title}</h1><p>${b.text}</p></div>${last?`<div class="chronicle-role-choices" role="group" aria-label="Первая рабочая задача">${roleChoices.map(r=>`<button type="button" data-chronicle="role" data-value="${r.id}" class="${selectedRole===r.id?'is-selected':''}" aria-pressed="${selectedRole===r.id}">${icon(r.path)}<span>${r.title}</span>${selectedRole===r.id?check:arrow}</button>`).join('')}</div>`:''}<div class="chronicle-controls"><button type="button" class="chronicle-back" data-chronicle="back" ${chapter===0&&beat===0?'disabled':''} aria-label="Предыдущая сцена">${back}<span>Назад</span></button><div class="chronicle-beats" aria-label="Сцена ${beat+1} из ${c.beats.length}">${c.beats.map((_,i)=>`<button type="button" data-chronicle="beat" data-value="${i}" class="${i<=beat?'is-read':''} ${i===beat?'is-current':''}" aria-label="Сцена ${i+1}" ${i===beat?'aria-current="step"':''}><span></span></button>`).join('')}</div><button type="button" class="primary" data-chronicle="next">${last?roleStart(selectedRole):b.action} ${arrow}</button></div><details class="chronicle-extra"><summary>Ещё один штрих к истории</summary><p>${c.more}</p><a href="${c.source}" target="_blank" rel="noopener">Источник: материалы «Очаково» ↗</a>${['kvass','people'].includes(c.id)?`<a href="${historySource}" target="_blank" rel="noopener">Хронология компании ↗</a>`:''}</details></div>`;
      const nav=root.querySelector('.chronicle-chapters'),active=nav.querySelector('.is-current');if(nav.scrollWidth>nav.clientWidth)nav.scrollLeft=active.offsetLeft-nav.offsetLeft-nav.clientWidth/2+active.offsetWidth/2;
      if(withMotion)animateScene();coach();
    }
    function animateScene(){
      if(!window.gsap||!motion())return;
      const sceneIndex=chapters[chapter].scene;
      context=gsap.context(()=>{
        const art=root.querySelector('.chronicle-art');if(art){const from=sceneIndex===2&&beat===1?{scale:1.065,xPercent:1.2}: {scale:1.025,xPercent:0};animations.add(gsap.fromTo(art,from,{scale:1,xPercent:0,duration:1.6,ease:'power2.out',clearProps:'transform'}));}
        animations.add(gsap.fromTo(root.querySelectorAll('.chronicle-copy > *'),{y:7,opacity:.45},{y:0,opacity:1,stagger:.07,duration:.42,ease:'power2.out',clearProps:'transform,opacity'}));
        if(sceneIndex===0&&beat>0){animations.add(gsap.fromTo(root.querySelector('.chronicle-power path'),{strokeDashoffset:600},{strokeDashoffset:0,duration:1.3,ease:'power2.inOut'}));animations.add(gsap.fromTo(root.querySelectorAll('.chronicle-windows i'),{opacity:0},{opacity:.7,duration:.7,stagger:.18,ease:'sine.inOut'}));}
        if(sceneIndex===1){animations.add(gsap.fromTo(root.querySelector('.chronicle-new-machine'),{clipPath:`inset(0 0 0 ${beat===0?100:beat===1?100:48}%)`},{clipPath:`inset(0 0 0 ${[100,48,0][beat]}%)`,duration:1.25,ease:'power3.inOut'}));if(beat>0)animations.add(gsap.fromTo(root.querySelectorAll('.chronicle-new-machine .chronicle-line-bottle'),{x:-25},{x:0,duration:.7,stagger:.17,ease:'power2.out',clearProps:'transform'}));}
        if(sceneIndex===2&&beat===2)animations.add(gsap.fromTo(root.querySelector('.chronicle-field-note'),{rotation:-6,y:25,opacity:0},{rotation:0,y:0,opacity:1,duration:.7,ease:'power3.out',clearProps:'transform,opacity'}));
        if(sceneIndex===3&&beat===1){const target=root.querySelector('.chronicle-tank').getBoundingClientRect();root.querySelectorAll('.culture-token').forEach((node,i)=>{const r=node.getBoundingClientRect();animations.add(gsap.fromTo(node,{x:0,y:0,opacity:1},{x:target.left+target.width/2-r.left-r.width/2,y:30,scale:.6,opacity:0,duration:1.1,delay:i*.3,ease:'power2.inOut',repeat:1,yoyo:true,repeatDelay:.15,clearProps:'transform,opacity'}));});}
        if(sceneIndex===3&&beat===2)animations.add(gsap.fromTo(root.querySelectorAll('.chronicle-kvass-pair>div'),{y:25,opacity:0},{y:0,opacity:1,duration:.65,stagger:.15,ease:'power3.out',clearProps:'transform,opacity'}));
        if(sceneIndex===4)animations.add(gsap.fromTo(root.querySelectorAll('.chronicle-route'),{strokeDashoffset:650},{strokeDashoffset:0,duration:1.2,stagger:.15,ease:'power2.inOut'}));
        if(sceneIndex===5)animations.add(gsap.fromTo(root.querySelectorAll('.chronicle-drink:not(:disabled)'),{y:24,opacity:.3},{y:0,opacity:1,duration:.65,stagger:.1,ease:'power3.out',clearProps:'transform,opacity'}));
        if(sceneIndex===6)animations.add(gsap.fromTo(root.querySelectorAll('.chronicle-team-spot'),{y:10,scale:.9,opacity:0},{y:0,scale:1,opacity:1,duration:.45,stagger:.1,ease:'power2.out',clearProps:'transform,opacity'}));
      },root);
    }
    function focusScene(){root.querySelector('h1').focus({preventScroll:true});root.scrollIntoView({block:'start',behavior:'instant'});}
    function click(e){const target=e.target.closest('[data-chronicle]');if(!target||!root.contains(target)||target.disabled||cleaned||done)return;const action=target.dataset.chronicle;
      if(action==='next'){if(beat<chapters[chapter].beats.length-1)beat++;else if(chapter<chapters.length-1){chapter++;beat=0;}else{done=true;onComplete?.({id:'intro',score:100,role:'Команда «Очаково»',learned:'Узнал историю от открытия комбината перед Олимпиадой-80 через обновление, экспедиции за рецептами и развитие площадок до новых напитков и команды.',nextId:selectedRole});return;}selectedDrink='';render();focusScene();}
      else if(action==='back'){if(beat>0)beat--;else if(chapter>0){chapter--;beat=chapters[chapter].beats.length-1;}render();focusScene();}
      else if(action==='chapter'){chapter=Number(target.dataset.value);beat=0;selectedDrink='';render();focusScene();}
      else if(action==='beat'){beat=Number(target.dataset.value);render();focusScene();}
      else if(action==='drink'){selectedDrink=target.dataset.value;root.querySelectorAll('.chronicle-drink').forEach(n=>{const active=n.dataset.value===selectedDrink;n.classList.toggle('is-picked',active);n.setAttribute('aria-pressed',String(active));});const d=drinks.find(d=>d.id===selectedDrink);root.querySelector('.chronicle-drink-caption').textContent=d.name+' · '+d.flavour;window.GameMotion?.coach({mood:'welcome',text:d.name+' — '+d.flavour.toLowerCase()+'. Один из напитков линейки, появившейся в 2022 году.'});if(window.gsap&&motion())animations.add(gsap.fromTo(target.querySelector('.chronicle-bottle'),{rotation:-4,y:0},{rotation:0,y:-7,duration:.3,yoyo:true,repeat:1,ease:'power2.out',clearProps:'transform'}));}
      else if(action==='role'){selectedRole=target.dataset.value;root.querySelectorAll('[data-chronicle="role"]').forEach(n=>{const active=n.dataset.value===selectedRole;n.classList.toggle('is-selected',active);n.setAttribute('aria-pressed',String(active));n.lastElementChild.outerHTML=active?check:arrow;});root.querySelector('[data-chronicle="next"]').innerHTML=roleStart(selectedRole)+' '+arrow;window.GameMotion?.coach({mood:'welcome',text:'Выбран участок «'+roleChoices.find(r=>r.id===selectedRole).title+'». Начнём с него.'});}
    }
    function sync(e){if(!e.detail.enabled){animations.forEach(t=>{t.totalProgress(1);t.kill();});animations.clear();}}
    root.addEventListener('click',click);document.addEventListener('ochakovo:motion',sync);render();
    return ()=>{cleaned=true;root.removeEventListener('click',click);document.removeEventListener('ochakovo:motion',sync);dispose();};
  }
  window.GameStory={mount};
})();
